package main; import "fmt"; import "strings"; import "reachability-scanner/engine"; import "reachability-scanner/internal/tui"; import tea "github.com/charmbracelet/bubbletea"; import "github.com/charmbracelet/lipgloss"; func main() { cfg := &engine.ScanConfig{DnsDiscoveryMode:true}; m := tui.NewModel(cfg); m.Update(tea.WindowSizeMsg{Width: 100, Height: 30}); view := m.View(); lines := strings.Split(view, "\n"); for i, line := range lines { fmt.Printf("Line %d width: %d\n", i, lipgloss.Width(line)) } }
